import * as T from './vendor/three.module.js';

// Original, unlettered Black Bay 54 interpretation. No photograph texture or brand emblems.
export function createDiveWatch(w,p,{worn=false}={}){
 const a=p.watchProfile,g=new T.Group(),diameter=25,thickness=diameter*a.thicknessMM/a.caseMM,front=thickness/2,parts=[],steel=w.mat('#b6bec1',{metalness:.8,roughness:.3}),satin=w.mat('#a7afb1',{metalness:.73,roughness:.46}),black=w.mat('#161b1c',{metalness:.14,roughness:.4}),gilt=w.mat('#bd9c65',{metalness:.65,roughness:.35}),lume=w.mat('#e5ddbb',{roughness:.7}),glass=w.mat('#b5cbd0',{transparent:true,opacity:.08,depthWrite:false,roughness:.13});
 const add=(geo,mat,x=0,y=0,z=0,role='')=>{const m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.userData.role=role;g.add(m);parts.push(role);return m;},box=(x,y,z,ww,h,d,mat,role)=>add(new T.BoxGeometry(ww,h,d),mat,x,y,z,role),disc=(r,h,z,mat,role)=>{const m=add(new T.CylinderGeometry(r,r,h,40),mat,0,0,z,role);m.rotation.x=Math.PI/2;return m;};
 disc(12.5,thickness,0,steel,'steel-case');disc(11.9,.8,front+.2,black,'aluminum-bezel');disc(9.7,.35,front+.5,black,'black-no-date-dial');const rim=add(new T.TorusGeometry(9.8,.2,6,40),steel,0,0,front+.7,'crystal-rim');
 for(let i=0;i<12;i++){const angle=i*Math.PI/6,x=Math.sin(angle)*8.2,y=Math.cos(angle)*8.2;if(!i){const shape=new T.Shape();shape.moveTo(-1.1,1);shape.lineTo(1.1,1);shape.lineTo(0,-1.3);shape.closePath();add(new T.ExtrudeGeometry(shape,{depth:.2,bevelEnabled:false}),lume,x,y,front+.8,'triangle-hour-marker');}else if(i%3===0){const b=box(x,y,front+.8,.9,2.1,.2,gilt,'baton-rim');b.rotation.z=-angle;const m=box(x,y,front+.95,.6,1.8,.2,lume,'baton-hour-marker');m.rotation.z=-angle;}else{const edge=add(new T.CylinderGeometry(.73,.73,.2,16),gilt,x,y,front+.8,'round-marker-rim');edge.rotation.x=Math.PI/2;const m=add(new T.CylinderGeometry(.56,.56,.2,16),lume,x,y,front+.95,'round-hour-marker');m.rotation.x=Math.PI/2;}}
 // Five-minute bezel marks only; there are no individual minute hash marks on this reference.
 const digits={0:'abcedf',1:'bc',2:'abged',3:'abgcd',4:'fgbc',5:'afgcd'},segments={a:[0,.7,.7,.12],b:[.38,.36,.12,.65],c:[.38,-.36,.12,.65],d:[0,-.7,.7,.12],e:[-.38,-.36,.12,.65],f:[-.38,.36,.12,.65],g:[0,0,.7,.12]};
 for(let n=1;n<=5;n++){const angle=n*Math.PI/3;for(const [digit,offset]of[[n,-.55],[0,.55]])for(const seg of digits[digit]){const [sx,sy,ww,h]=segments[seg],xx=offset+sx,yy=10.9+sy,m=box(xx*Math.cos(angle)+yy*Math.sin(angle),-xx*Math.sin(angle)+yy*Math.cos(angle),front+.68,ww,h,.08,lume,'bezel-numeral');m.rotation.z=-angle;}}
 for(const i of[1,3,5,7,9,11]){const angle=i*Math.PI/6,m=box(Math.sin(angle)*10.9,Math.cos(angle)*10.9,front+.68,.35,1.4,.08,lume,'five-minute-bezel-mark');m.rotation.z=-angle;}const zero=new T.Shape();zero.moveTo(-.7,.5);zero.lineTo(.7,.5);zero.lineTo(0,-.65);zero.closePath();add(new T.ExtrudeGeometry(zero,{depth:.1,bevelEnabled:false}),lume,0,11.05,front+.68,'bezel-zero-triangle');
 const hand=(angle,length,width,role)=>{const m=box(Math.sin(angle)*length/2,Math.cos(angle)*length/2,front+1.15,width,length,.17,gilt,role);m.rotation.z=-angle;const inset=box(Math.sin(angle)*length/2,Math.cos(angle)*length/2,front+1.27,width*.6,length-.35,.12,lume,role+'-lume');inset.rotation.z=-angle;};
 hand(-Math.PI/3,5.2,.85,'hour-shaft');const snow=box(-Math.sin(Math.PI/3)*4.15,Math.cos(Math.PI/3)*4.15,front+1.2,1.9,1.9,.2,gilt,'snowflake-hour-hand');snow.rotation.z=Math.PI/3+Math.PI/4;const snowLume=box(snow.position.x,snow.position.y,front+1.34,1.48,1.48,.12,lume,'snowflake-lume');snowLume.rotation.z=snow.rotation.z;hand(Math.PI/3,7.2,.5,'minute-hand');
 const second=box(-2.1,-.9,front+1.5,10,.12,.1,gilt,'seconds-hand');second.rotation.z=.4;const dot=add(new T.CylinderGeometry(.42,.42,.14,14),lume,-4.9,-2.08,front+1.55,'lollipop-seconds');dot.rotation.x=Math.PI/2;disc(.48,.2,front+1.55,gilt,'hand-hub');
 const crown=add(new T.CylinderGeometry(1.35,1.35,2.6,16),steel,13.3,0,0,'plain-screw-down-crown');crown.rotation.z=Math.PI/2;for(const sign of[-1,1])for(const x of[-6,6])box(x,sign*12,0,2.4,5,thickness*.65,steel,'lug');
 if(worn){const ring=add(new T.TorusGeometry(16,2,8,32),satin,0,0,-15,'bracelet-loop');ring.rotation.x=Math.PI/2;ring.scale.y=.8;}else for(const sign of[-1,1])for(let i=0;i<7;i++)for(const dx of[-4.2,0,4.2])box(dx,sign*(15+i*3.5),0,3.9,3.1,2.5,satin,'three-link-bracelet');
 const dome=new T.SphereGeometry(9.6,28,12,0,Math.PI*2,0,Math.PI/2);dome.rotateX(Math.PI/2);dome.scale(1,1,.07);add(dome,glass,0,0,front+1.8,'illustrative-domed-crystal');
 g.updateMatrixWorld(true);const batches=new Map();for(const o of[...g.children]){const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrixWorld);if(!batches.has(o.material))batches.set(o.material,{position:[],normal:[]});const b=batches.get(o.material);for(const key of['position','normal'])b[key].push(...geo.attributes[key].array);geo.dispose();o.geometry.dispose();g.remove(o);}for(const[mat,b]of batches){const geo=new T.BufferGeometry();for(const key of['position','normal'])geo.setAttribute(key,new T.Float32BufferAttribute(b[key],3));const m=w.mesh(geo,mat,g);m.castShadow=m.receiveShadow=true;}
 g.scale.setScalar(worn?.06*a.caseMM/41:1);g.userData={productId:p.id,role:worn?'worn-watch':'watch-model',caseMM:a.caseMM,thicknessMM:a.thicknessMM,lugMM:a.lugMM,bodyDiameter:diameter,bodyThickness:thickness,band:a.band,source:p.source,parts,dateDisplay:false,bezelMinuteHashes:false,unlettered:true};return g;
}
